UPDATE ICOMECCT
SET CONT_TITLE			= #{st_contract_name}
	,CONTENT			= #{st_content}
	,ORI_CONTENT		= #{st_oriContent}
	,CONT_DATE			= #{st_cont_date}
	,START_DATE			= #{st_start_date}
	,END_DATE			= #{st_end_date}
	,SPPLR_NAME		= #{st_spplr_nm}
	,CHANGE_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
	,CHANGE_TIME		= TO_CHAR(SYSDATE,'HH24MISS')
	,CHANGE_USER_ID	= #{st_user_id}
WHERE CONT_NO = #{st_cont_no}
AND CONT_COUNT= #{st_cont_count}
